-- ============================================================================
-- 256 — تعديل القانون رقم 3 لسنة 2005 (حماية المنافسة ومنع الممارسات الاحتكارية) بالقانون رقم 190 لسنة 2008
-- ----------------------------------------------------------------------------
-- المصدر: ملف PDF من 3 صفحات ممسوحة ضوئياً (بلا طبقة نص) قدمه المالك: الجريدة الرسمية - العدد 25 مكرر (أ) فى 22 يونية سنة 2008 (الصفحات 9 إلى 11): القانون 190 لسنة 2008 بتعديل بعض أحكام القانون 3 لسنة 2005. قُرئت الصفحات الثلاث بصرياً مرتين (بالتكبير للأرقام والمبالغ)، والإملاء كما طُبع.
-- نطاق التعديل: المادة الأولى تستبدل البندين (ب) و(د) من المادة 6 والبند (هـ) من المادة 8 والفقرة الأولى من البند 2 من المادة 11 والمادة 22 (غرامة من 100 ألف إلى 300 مليون جنيه وتضاعف فى العود)؛ والمادة الثانية تضيف فقرة ثالثة إلى المادة 11 وفقرة ثانية إلى المادة 19 (إخطار من يتجاوز رقم أعماله 100 مليون جنيه) والمادتين 22 مكرراً و22 مكرراً (أ)؛ والمادة الثالثة النشر والعمل من اليوم التالى لتاريخ النشر.
-- التواريخ: النشر 2008-06-22 فيكون العمل من 2008-06-23 (مادة 3). النسخة الأصلية تُغلق بـ effective_to = 2008-06-22 كى تُبقى استعلامات النص الحالى (effective_to IS NULL) على النسخة الجديدة وحدها.
-- التمثيل (نمط REPLACE): المواد 6 و8 و11 و19 و22 تحمل نسختين (الأصلية status=amended مغلقة بالتاريخ، والجديدة active) والصف يحمل النص الجديد؛ المادتان الجديدتان 22 مكرراً (suffix=1) و22 مكرراً (أ) (suffix=2) بنسخة واحدة. النص الجديد للمواد المعدلة جزئياً مبنى بتطبيق الاستبدال على النص الأصلى المخزن (المطابق لهجرة 225 بالمجموع الاختبارى) فلا يتحرك فيها حرف غير المعدل.
-- تنبيهات: (1) موضع الفقرة الثالثة المضافة للمادة 11 (آخر المادة) مأخوذ من ترتيب الفقرات ولم يُطابق على نص موحد منشور. (2) الفقرة الثانية الأصلية من المادة 22 (الغرامة البديلة عن المصادرة) سقطت لأن النص البديل لا يتضمنها. (3) القانون عُدل لاحقاً بالقانون 175 لسنة 2022 (جوهرى) ولم يُرفع نصه بعد، فيبقى القانون «معدلاً» وقد لا يطابق الصيغة النافذة. (4) المواد المعدلة بلا embedding فتحتاج إعادة تضمين.
-- الطريقة: ترفض التشغيل إن لم يوجد القانون 3/2005 (بعنوان «المنافسة») أو إن اختلف نص أى مادة معدلة عن نص هجرة 225؛ قابلة لإعادة التشغيل (تتخطى ما طُبق). ولا تمس أى قانون آخر.
-- ============================================================================

CREATE TEMP TABLE m256_amend (
  article_no int NOT NULL, orig_body text NOT NULL, orig_md5 text NOT NULL, new_body text NOT NULL, new_md5 text NOT NULL, note text NOT NULL
) ON COMMIT DROP;
CREATE TEMP TABLE m256_new (
  article_no int NOT NULL, suffix int NOT NULL, loc text NOT NULL, body text NOT NULL, body_md5 text NOT NULL, note text NOT NULL
) ON COMMIT DROP;

INSERT INTO m256_amend VALUES
(6,$o256$يحظر الاتفاق أو التعاقد بين أشخاص متنافسة فى أية سوق معينة إذا كان من شأنه إحداث أى مما يأتى :
( أ ) رفع أو خفض أو تثبيت أسعار البيع أو الشراء للمنتجات محل التعامل .
( ب ) اقتسام أسواق المنتجات أو تخصيصها على أساس من المناطق الجغرافية أو مراكز التوزيع أو نوعية العملاء أو السلع أو المواسم أو الفترات الزمنية .
( جـ ) التنسيق فيما يتعلق بالتقدم أو الامتناع عن الدخول فى المناقصات والمزايدات والممارسات وسائر عروض التوريد .
( د ) تقييد عمليات التصنيع أو التوزيع أو التسويق أو الحد من توزيع الخدمات أو نوعها أو حجمها أو وضع شروط أو قيود على توفيرها .$o256$,'24cb9b432f4f9d289f2fac583a26f216',$n256$يحظر الاتفاق أو التعاقد بين أشخاص متنافسة فى أية سوق معينة إذا كان من شأنه إحداث أى مما يأتى :
( أ ) رفع أو خفض أو تثبيت أسعار البيع أو الشراء للمنتجات محل التعامل .
( ب ) اقتسام أسواق المنتجات أو تخصيصها على أساس من المناطق الجغرافية أو مراكز التوزيع أو نوعية العملاء أو السلع أو الحصص السوقية أو المواسم أو الفترات الزمنية .
( جـ ) التنسيق فيما يتعلق بالتقدم أو الامتناع عن الدخول فى المناقصات والمزايدات والممارسات وسائر عروض التوريد .
( د ) تقييد عمليات التصنيع أو الإنتاج أو التوزيع أو التسويق للسلع أو الخدمات ويشمل ذلك تقييد نوع المنتج أو حجمه أو الحد من توافره .$n256$,'f9e1c20bd10ce88577d5d513b237c76b',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) استبدل البندين (ب) و(د) من المادة 6: أُضيفت «الحصص السوقية» إلى أسس اقتسام الأسواق فى (ب)، وأُعيدت صياغة (د) فصارت «تقييد عمليات التصنيع أو الإنتاج أو التوزيع أو التسويق للسلع أو الخدمات ويشمل ذلك تقييد نوع المنتج أو حجمه أو الحد من توافره». البنود (أ) و(جـ) ومقدمة المادة دون تغيير.$c256$),
(8,$o256$يحظر على من تكون له السيطرة على سوق معنية القيام بأى مما يأتى :
( أ ) فعل من شأنه أن يؤدى إلى عدم التصنيع أو الإنتاج أو التوزيع لمنتج لفترة أو فترات محددة .
( ب ) الامتناع عن إبرام صفقات بيع أو شراء منتج مع أى شخص أو وقف التعامل معه على نحو يؤدى إلى الحد من حريته فى دخول السوق أو الخروج منه فى أى وقت .
( جـ ) فعل من شأنه أن يؤدى إلى الاقتصار على توزيع منتج دون غيره ، على أساس مناطق جغرافية أو مراكز توزيع أو عملاء أو مواسم أو فترات زمنية وذلك بين أشخاص ذوى علاقة رأسية .
( د ) تعليق إبرام عقد أو اتفاق بيع أو شراء لمنتج على شرط قبول التزامات أو منتجات تكون بطبيعتها أو بموجب الاستخدام التجارى للمنتج غير مرتبطة به أو بمحل التعامل الأصلى أو الاتفاق .
( هـ ) التمييز بين بائعين أو مشترين تتشابه مراكزهم التجارية فى أسعار البيع أو الشراء أو فى شروط التعامل .
( و ) الامتناع عن إنتاج أو إتاحة منتج شحيح متى كان إنتاجه أو إتاحته ممكنة اقتصاديا .
( ز ) أن يشترط على المتعاملين معه ألا يتيحوا لشخص منافس له استخدام ما يحتاجه من مرافقهم أو خدماتهم ، رغم أن إتاحة هذا الاستخدام ممكن اقتصاديا .
( ح ) بيع منتجات بسعر يقل عن تكلفتها الحدية أو متوسط تكلفتها المتغيرة .
( ط ) إلزام مورد بعدم التعامل مع منافس .
وتبين اللائحة التنفيذية لهذا القانون شروط وإجراءات تطبيق أحكام هذه المادة .$o256$,'9c154b87a577280294a65874fd091b75',$n256$يحظر على من تكون له السيطرة على سوق معنية القيام بأى مما يأتى :
( أ ) فعل من شأنه أن يؤدى إلى عدم التصنيع أو الإنتاج أو التوزيع لمنتج لفترة أو فترات محددة .
( ب ) الامتناع عن إبرام صفقات بيع أو شراء منتج مع أى شخص أو وقف التعامل معه على نحو يؤدى إلى الحد من حريته فى دخول السوق أو الخروج منه فى أى وقت .
( جـ ) فعل من شأنه أن يؤدى إلى الاقتصار على توزيع منتج دون غيره ، على أساس مناطق جغرافية أو مراكز توزيع أو عملاء أو مواسم أو فترات زمنية وذلك بين أشخاص ذوى علاقة رأسية .
( د ) تعليق إبرام عقد أو اتفاق بيع أو شراء لمنتج على شرط قبول التزامات أو منتجات تكون بطبيعتها أو بموجب الاستخدام التجارى للمنتج غير مرتبطة به أو بمحل التعامل الأصلى أو الاتفاق .
( هـ ) التمييز فى أسعار البيع أو الشراء أو فى شروط التعامل بين بائعين أو مشترين تتشابه مراكزهم التعاقدية .
( و ) الامتناع عن إنتاج أو إتاحة منتج شحيح متى كان إنتاجه أو إتاحته ممكنة اقتصاديا .
( ز ) أن يشترط على المتعاملين معه ألا يتيحوا لشخص منافس له استخدام ما يحتاجه من مرافقهم أو خدماتهم ، رغم أن إتاحة هذا الاستخدام ممكن اقتصاديا .
( ح ) بيع منتجات بسعر يقل عن تكلفتها الحدية أو متوسط تكلفتها المتغيرة .
( ط ) إلزام مورد بعدم التعامل مع منافس .
وتبين اللائحة التنفيذية لهذا القانون شروط وإجراءات تطبيق أحكام هذه المادة .$n256$,'744e1e7d7704b8bfaee98b789a88f3de',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) استبدل البند (هـ) من المادة 8: صار «التمييز فى أسعار البيع أو الشراء أو فى شروط التعامل بين بائعين أو مشترين تتشابه مراكزهم التعاقدية» (كان «مراكزهم التجارية»). باقى البنود دون تغيير.$c256$),
(11,$o256$ينشأ جهاز يسمى جهاز حماية المنافسة ومنع الممارسات الاحتكارية يكون مقره القاهرة الكبرى وتكون له الشخصية الاعتبارية العامة ، يتبع الوزير المختص ، ويتولى على الأخص ما يلى :
( 1 ) تلقى الطلبات باتخاذ إجراءات التقصى والبحث وجمع الاستدلالات والأمر باتخاذ هذه الإجراءات بالنسبة لحالات الاتفاقات والممارسات الضارة بالمنافسة ، وذلك طبقاً للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
( 2 ) تلقى الإخطارات من الأشخاص ، فور اكتسابها أى أصول أو حقوق ملكية أو انتفاع أو أسهم ، أو إقامة اتحادات أو اندماجات أو دمج ، أو الجمع بين إدارة شخصين أو أكثر .
وتحدد اللائحة التنفيذية لهذا القانون ميعاد وبيانات الإخطار والمستندات التى يجب إرفاقها به وإجراءات تقديمه .
( 3 ) إعداد قاعدة بيانات ومعلومات متكاملة عن النشاط الاقتصادى وتحديثها وتطويرها بصورة دائمة بما يخدم عمل الجهاز فى كافة المجالات المرتبطة بحماية المنافسة .
وإنشاء قاعدة بيانات وإجراء الدراسات والبحوث اللازمة لكشف الحالات الضارة بالمنافسة .
( 4 ) اتخاذ التدابير المنصوص عليها فى المادة ( 20 ) من هذا القانون .
( 5 ) إبداء الرأى فى مشروعات القوانين واللوائح المتعلقة بتنظيم المنافسة .
( 6 ) التنسيق مع الأجهزة النظيرة فى الدول الأخرى بالنسبة للأمور ذات الاهتمام المشترك .
( 7 ) تنظيم برامج تدريبية وتثقيفية بهدف التوعية بأحكام هذا القانون ومبادئ السوق الحرة بوجه عام .
( 8 ) إصدار نشرة دورية تتضمن القرارات والتوصيات والإجراءات والتدابير التى يتخذها الجهاز وغير ذلك مما يتصل بشئونه .
( 9 ) إعداد تقرير سنوى عن أنشطة الجهاز وخطته المستقبلية ومقترحاته ليعرض على الوزير المختص بعد اعتماده من مجلس الإدارة ، وترسل نسخة منه إلى مجلسى الشعب والشورى .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات التى يتبعها الجهاز لتحقيق وإثبات الأفعال التى تتضمن أو تشكل مخالفة لأحكام هذا القانون .$o256$,'a0fc7f71a38160e5dceee2f936b8dbd3',$n256$ينشأ جهاز يسمى جهاز حماية المنافسة ومنع الممارسات الاحتكارية يكون مقره القاهرة الكبرى وتكون له الشخصية الاعتبارية العامة ، يتبع الوزير المختص ، ويتولى على الأخص ما يلى :
( 1 ) تلقى الطلبات باتخاذ إجراءات التقصى والبحث وجمع الاستدلالات والأمر باتخاذ هذه الإجراءات بالنسبة لحالات الاتفاقات والممارسات الضارة بالمنافسة ، وذلك طبقاً للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
( 2 ) تلقى الإخطارات المنصوص عليها فى الفقرة الثانية من المادة ( 19 ) من هذا القانون .
وتحدد اللائحة التنفيذية لهذا القانون ميعاد وبيانات الإخطار والمستندات التى يجب إرفاقها به وإجراءات تقديمه .
( 3 ) إعداد قاعدة بيانات ومعلومات متكاملة عن النشاط الاقتصادى وتحديثها وتطويرها بصورة دائمة بما يخدم عمل الجهاز فى كافة المجالات المرتبطة بحماية المنافسة .
وإنشاء قاعدة بيانات وإجراء الدراسات والبحوث اللازمة لكشف الحالات الضارة بالمنافسة .
( 4 ) اتخاذ التدابير المنصوص عليها فى المادة ( 20 ) من هذا القانون .
( 5 ) إبداء الرأى فى مشروعات القوانين واللوائح المتعلقة بتنظيم المنافسة .
( 6 ) التنسيق مع الأجهزة النظيرة فى الدول الأخرى بالنسبة للأمور ذات الاهتمام المشترك .
( 7 ) تنظيم برامج تدريبية وتثقيفية بهدف التوعية بأحكام هذا القانون ومبادئ السوق الحرة بوجه عام .
( 8 ) إصدار نشرة دورية تتضمن القرارات والتوصيات والإجراءات والتدابير التى يتخذها الجهاز وغير ذلك مما يتصل بشئونه .
( 9 ) إعداد تقرير سنوى عن أنشطة الجهاز وخطته المستقبلية ومقترحاته ليعرض على الوزير المختص بعد اعتماده من مجلس الإدارة ، وترسل نسخة منه إلى مجلسى الشعب والشورى .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات التى يتبعها الجهاز لتحقيق وإثبات الأفعال التى تتضمن أو تشكل مخالفة لأحكام هذا القانون .
ويلتزم الأشخاص بموافاة الجهاز بما يطلبه من البيانات أو الأوراق أو المستندات اللازمة لممارسة اختصاصاته وذلك خلال المواعيد التى يحددها .$n256$,'43f2762f9c8a92bd6d0efce3ffb0b48a',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) استبدل الفقرة الأولى من البند 2 من المادة 11 (صار تلقى الإخطارات المنصوص عليها فى الفقرة الثانية من المادة 19)، وأضاف فقرة ثالثة بإلزام الأشخاص بموافاة الجهاز بما يطلبه من بيانات وأوراق ومستندات خلال المواعيد التى يحددها. موضع الفقرة المضافة (آخر المادة، بعد الفقرة الأخيرة المحيلة إلى اللائحة) مأخوذ من ترتيب الفقرات ولم يُطابق على نص موحد منشور.$c256$),
(19,$o256$يجوز لأى شخص إبلاغ الجهاز بأية مخالفة تقع لأحكام هذا القانون .$o256$,'31ca95c46212e1a4e5257a7619e875c9',$n256$يجوز لأى شخص إبلاغ الجهاز بأية مخالفة تقع لأحكام هذا القانون .
وعلى الأشخاص الذين يتجاوز رقم أعمالهم السنوى فى آخر ميزانية مائة مليون جنيه أن يخطروا الجهاز لدى اكتسابهم لأصول أو حقوق ملكية أو انتفاع أو أسهم أو إقامة اتحادات أو اندماجات أو دمج أو استحواذ أو الجمع بين إدارة شخصين أو أكثر بذلك وفقًا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$n256$,'543ccb51104911b80d0ac9208bfa0709',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) أضاف فقرة ثانية إلى المادة 19: إخطار الجهاز على الأشخاص الذين يتجاوز رقم أعمالهم السنوى فى آخر ميزانية مائة مليون جنيه عند الاستحواذ والاندماج وما فى حكمهما، وفق ما تحدده اللائحة التنفيذية.$c256$),
(22,$o256$مع عدم الإخلال بأية عقوبة أشد ينص عليها أى قانون آخر يعاقب على كل مخالفة لأحكام أى من المواد ( 6 ، 7 ، 8 ) من هذا القانون بغرامة لاتقل عن ثلاثين ألف جنيه ولا تجاوز عشرة ملايين جنيه .
وللمحكمة بدلاً من الحكم بالمصادرة أن تقضى بغرامة بديلة تعادل قيمة المنتج محل النشاط المخالف .$o256$,'77c861d733f13864987d31f12f467ebf',$n256$مع عدم الإخلال بأية عقوبة أشد ينص عليها أى قانون آخر يعاقب على كل مخالفة لأحكام أى من المواد 6 ، 7 ، 8 من هذا القانون بغرامة لا يقل حدها الأدنى عن مائة ألف جنيه ، ولا يجاوز حدها الأقصى ثلاثمائة مليون جنيه ، وتضاعف الغرامة بحديها فى حالة العود .$n256$,'4053252e92b86736b0cdd295463bdc14',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) استبدل المادة 22 بالكامل: الغرامة على مخالفة المواد 6 و7 و8 صارت لا يقل حدها الأدنى عن مائة ألف جنيه ولا يجاوز حدها الأقصى ثلاثمائة مليون جنيه (كانت من ثلاثين ألفاً إلى عشرة ملايين جنيه) وتضاعف بحديها فى حالة العود؛ وسقطت الفقرة الثانية الأصلية (الغرامة البديلة عن المصادرة) لأن النص البديل لا يتضمنها.$c256$);

INSERT INTO m256_new VALUES
(22,1,$l256$المادة 22 مكرراً$l256$,$n256$يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز مائة ألف جنيه كل من :
1 - أخل بواجب الإخطار المنصوص عليه فى الفقرة الثانية من المادة ( 19 ) من هذا القانون .
2 - امتنع عن موافاة الجهاز بالبيانات أو الأوراق أو المستندات المنصوص عليها فى الفقرة الثالثة من المادة ( 11 ) من هذا القانون .
ومع عدم الإخلال بأية عقوبة أشد تكون العقوبة الغرامة التى لا تقل عن عشرين ألف جنيه ولا تجاوز مائتى ألف جنيه فى حالة إمداد الجهاز ببيانات أو أوراق أو مستندات غير صحيحة مع العلم بذلك .$n256$,'425989975f160481edd2b0ceb8e5e52f',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) أضاف المادة 22 مكرراً: غرامة من عشرة آلاف إلى مائة ألف جنيه عن الإخلال بواجب الإخطار (م19 فقرة ثانية) أو الامتناع عن موافاة الجهاز بالبيانات (م11 فقرة ثالثة)، وغرامة من عشرين ألفاً إلى مائتى ألف جنيه عند إمداد الجهاز ببيانات غير صحيحة مع العلم.$c256$),
(22,2,$l256$المادة 22 مكرراً (أ)$l256$,$n256$مع عدم الإخلال بأية عقوبة أشد ينص عليها القانون ، يعاقب بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز خمسمائة ألف جنيه كل من لم يلتزم بتنفيذ قرارات الجهاز الصادرة تطبيقًا لنص المادة ( 20 ) من هذا القانون .
وفى حالة العود تضاعف العقوبة بحديها الأدنى والأقصى .$n256$,'dab0852aa693ffbc19326007f7efa2ea',$c256$القانون 190 لسنة 2008 (الجريدة الرسمية العدد 25 مكرر (أ) فى 22/6/2008؛ العمل به من 23/6/2008) أضاف المادة 22 مكرراً (أ): غرامة من عشرين ألفاً إلى خمسمائة ألف جنيه على من لم يلتزم بتنفيذ قرارات الجهاز الصادرة تطبيقاً للمادة 20، وتضاعف العقوبة بحديها فى حالة العود.$c256$);

DO $m256$
DECLARE
  v_law uuid;
  v_title text;
  r record;
  v_art uuid;
  v_vcnt int;
  v_v1 record;
  v_v2 record;
  v_applied int := 0;
  v_skipped int := 0;
  v_added int := 0;
  v_cnt int;
BEGIN
  IF (SELECT count(*) FROM m256_amend WHERE md5(orig_body) <> orig_md5 OR md5(new_body) <> new_md5) <> 0
     OR (SELECT count(*) FROM m256_new WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[256] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m256_amend) <> 5 OR (SELECT count(*) FROM m256_new) <> 2
     OR (SELECT sum(char_length(new_body)) FROM m256_amend) + (SELECT sum(char_length(body)) FROM m256_new) <> 4762 THEN
    RAISE EXCEPTION '[256] عدد الصفوف أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=3 AND law_year=2005 AND kind='law';
  IF v_law IS NULL THEN
    RAISE EXCEPTION '[256] القانون 3/2005 غير موجود: يجب تشغيل 225 أولاً';
  END IF;
  IF v_title NOT LIKE '%المنافسة%' THEN
    RAISE EXCEPTION '[256] مستند آخر برقم 3 لسنة 2005 (%): لا يُطبَّق التعديل عليه', v_title;
  END IF;

  -- ===== المواد المعدلة =====
  FOR r IN SELECT * FROM m256_amend ORDER BY article_no LOOP
    SELECT a.id INTO v_art FROM articles a WHERE a.law_id = v_law AND a.article_no = r.article_no AND a.article_suffix_order = 0;
    IF v_art IS NULL THEN
      RAISE EXCEPTION '[256] المادة % غير موجودة', r.article_no;
    END IF;
    SELECT count(*) INTO v_vcnt FROM article_versions WHERE article_id = v_art;
    SELECT * INTO v_v1 FROM article_versions WHERE article_id = v_art AND version_no = 1;
    SELECT * INTO v_v2 FROM article_versions WHERE article_id = v_art AND version_no = 2;

    IF v_vcnt = 2 AND v_v2.body = r.new_body AND v_v2.amended_by_law_no = 190 AND v_v2.effective_to IS NULL THEN
      v_skipped := v_skipped + 1;      -- طُبق من قبل
    ELSIF v_vcnt = 1 AND v_v1.status = 'active' AND v_v1.effective_to IS NULL AND md5(v_v1.body) = r.orig_md5 THEN
      UPDATE article_versions SET status = 'amended', effective_to = DATE '2008-06-22' WHERE id = v_v1.id;
      INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
      VALUES (v_art, 2, r.new_body, DATE '2008-06-23', NULL, 'active', 190, 2008, r.note);
      UPDATE articles SET body = r.new_body, updated_at = now() WHERE id = v_art;
      v_applied := v_applied + 1;
    ELSE
      RAISE EXCEPTION '[256] حالة غير متوقعة للمادة % (عدد النسخ %): لا يُطبَّق التعديل', r.article_no, v_vcnt;
    END IF;
  END LOOP;

  -- ===== المواد المضافة =====
  FOR r IN SELECT * FROM m256_new ORDER BY suffix LOOP
    SELECT a.id INTO v_art FROM articles a WHERE a.law_id = v_law AND a.article_no = r.article_no AND a.article_suffix_order = r.suffix;
    IF v_art IS NULL THEN
      INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
      VALUES (v_law, r.article_no, r.suffix, r.loc, r.body) RETURNING id INTO v_art;
      INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
      VALUES (v_art, 1, r.body, DATE '2008-06-23', NULL, 'active', 190, 2008, r.note);
      v_added := v_added + 1;
    ELSE
      IF (SELECT body FROM articles WHERE id = v_art) <> r.body THEN
        RAISE EXCEPTION '[256] المادة % (suffix %) موجودة بنص مختلف', r.article_no, r.suffix;
      END IF;
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  -- ===== المواد غير المعدلة: ملاحظة النسخة تستثنى 190/2008 وتبقى 175/2022 معلقة =====
  UPDATE article_versions av SET change_note = $k256$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، وهذه المادة لم يمسها القانون 190 لسنة 2008. عدل القانون لاحقا بالقانون 175 لسنة 2022 (جوهرى بحسب ملاحظات المشروع) ونصه لم يرفع بعد، فقد لا يطابق هذا النص الصيغة النافذة حاليا$k256$
    FROM articles a
   WHERE a.id = av.article_id AND a.law_id = v_law AND av.version_no = 1 AND av.status = 'active'
     AND av.change_note = $o256$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005؛ عدل القانون لاحقا (القانونان 190 لسنة 2008 و175 لسنة 2022 بحسب ملاحظات المشروع) ونصوص التعديلات لم ترفع بعد، فقد لا يطابق هذا النص الصيغة النافذة حاليا$o256$;

  -- ملاحظة النسخة الأصلية للمواد المعدلة: تحيل إلى النسخة 2 بدل الادعاء بأن التعديل لم يرفع
  UPDATE article_versions av SET change_note = $z256$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، سرى حتى 22/6/2008 وعدلته المادة المقابلة من القانون 190 لسنة 2008 (انظر النسخة 2). عدل القانون لاحقا بالقانون 175 لسنة 2022 ونصه لم يرفع بعد$z256$
    FROM articles a
   WHERE a.id = av.article_id AND a.law_id = v_law AND av.version_no = 1 AND av.status = 'amended'
     AND av.change_note = $o256$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005؛ عدل القانون لاحقا (القانونان 190 لسنة 2008 و175 لسنة 2022 بحسب ملاحظات المشروع) ونصوص التعديلات لم ترفع بعد، فقد لا يطابق هذا النص الصيغة النافذة حاليا$o256$;

  -- ===== سجل القانون =====
  UPDATE laws SET
    last_amended_at = DATE '2008-06-23',
    title = $t256$القانون رقم 3 لسنة 2005 بإصدار قانون حماية المنافسة ومنع الممارسات الاحتكارية (النص الأصلى المنشور فى 15/2/2005 معدلاً بالقانون رقم 190 لسنة 2008؛ دون تعديل القانون 175 لسنة 2022)$t256$
   WHERE id = v_law AND (last_amended_at IS NULL OR last_amended_at < DATE '2008-06-23');

  -- ===== التحقق النهائى =====
  SELECT count(*) INTO v_cnt FROM articles WHERE law_id = v_law;
  IF v_cnt <> 32 THEN
    RAISE EXCEPTION '[256] عدد صفوف القانون % بدل 32', v_cnt;
  END IF;
  -- نسخة حالية واحدة بالضبط لكل مادة (الاستعلامات تعتمد effective_to IS NULL)
  SELECT count(*) INTO v_cnt FROM articles a WHERE a.law_id = v_law
     AND (SELECT count(*) FROM article_versions v WHERE v.article_id = a.id AND v.effective_to IS NULL) <> 1;
  IF v_cnt <> 0 THEN
    RAISE EXCEPTION '[256] % مادة بلا نسخة حالية وحيدة', v_cnt;
  END IF;
  -- نص الصف = نص النسخة الحالية
  SELECT count(*) INTO v_cnt FROM articles a JOIN article_versions v ON v.article_id = a.id AND v.effective_to IS NULL
   WHERE a.law_id = v_law AND a.body <> v.body;
  IF v_cnt <> 0 THEN
    RAISE EXCEPTION '[256] % مادة نصها لا يطابق نسختها الحالية', v_cnt;
  END IF;
  SELECT count(*) INTO v_cnt FROM m256_amend m JOIN articles a ON a.law_id = v_law AND a.article_no = m.article_no AND a.article_suffix_order = 0
    JOIN article_versions v1 ON v1.article_id = a.id AND v1.version_no = 1 AND v1.status = 'amended' AND v1.effective_to = DATE '2008-06-22' AND md5(v1.body) = m.orig_md5
    JOIN article_versions v2 ON v2.article_id = a.id AND v2.version_no = 2 AND v2.status = 'active' AND v2.effective_to IS NULL AND v2.effective_from = DATE '2008-06-23' AND v2.body = m.new_body AND a.body = m.new_body;
  IF v_cnt <> 5 THEN
    RAISE EXCEPTION '[256] المواد المعدلة المتحقق منها % بدل 5', v_cnt;
  END IF;
  RAISE NOTICE '[256] تعديل 190/2008 على 3/2005: مواد معدلة=%, مضافة=%, متخطاة=%', v_applied, v_added, v_skipped;
END
$m256$;
